// ============================================================
// AI OUTPUT → TOLERANT BLOG PARSER → GHOST LEXICAL
// ============================================================

let raw = $json.output;

// ------------------------------------------------------------
// 1. Get AI response
// ------------------------------------------------------------

if (typeof raw !== "string") {
  // Some AI nodes may return another field depending on configuration
  raw =
    $json.text ??
    $json.content ??
    $json.response ??
    "";

  if (typeof raw !== "string") {
    raw = String(raw || "");
  }
}

raw = raw.trim();

if (!raw) {
  throw new Error("AI returned an empty response.");
}


// ------------------------------------------------------------
// 2. Remove surrounding Markdown code fences
// ------------------------------------------------------------

raw = raw
  .replace(/^```(?:json|markdown|md|text)?\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();


// ------------------------------------------------------------
// 3. Try JSON first
// ------------------------------------------------------------

let blog = null;

try {
  blog = JSON.parse(raw);
} catch (error) {
  // Not JSON.
  // That's OK — we'll treat it as Markdown/plain text.
}


// ------------------------------------------------------------
// 4. If JSON was returned, normalize it
// ------------------------------------------------------------

if (blog && typeof blog === "object") {

  // Make sure expected fields exist
  blog.title = blog.title || "Untitled Blog";
  blog.slug = blog.slug || "";

  blog.introduction =
    typeof blog.introduction === "string"
      ? blog.introduction
      : "";

  blog.sections =
    Array.isArray(blog.sections)
      ? blog.sections
      : [];

  blog.key_takeaways =
    Array.isArray(blog.key_takeaways)
      ? blog.key_takeaways
      : [];

  blog.conclusion =
    typeof blog.conclusion === "string"
      ? blog.conclusion
      : "";

} else {

  // ----------------------------------------------------------
  // 5. Not JSON → parse Markdown/plain text
  // ----------------------------------------------------------

  blog = parseMarkdownBlog(raw);
}


// ============================================================
// MARKDOWN / PLAIN TEXT PARSER
// ============================================================

function parseMarkdownBlog(text) {

  const lines = text
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .split("\n");

  let title = "";
  const bodyLines = [];

  // ----------------------------------------------------------
  // Find title
  // ----------------------------------------------------------

  for (let i = 0; i < lines.length; i++) {

    const line = lines[i].trim();

    if (!line) {
      continue;
    }

    // # Title
    if (/^#\s+/.test(line)) {
      title = line
        .replace(/^#\s+/, "")
        .replace(/\*\*/g, "")
        .trim();

      lines.splice(i, 1);
      break;
    }

    // **Title**
    if (/^\*\*.+\*\*$/.test(line)) {
      title = line
        .replace(/^\*\*/, "")
        .replace(/\*\*$/, "")
        .trim();

      lines.splice(i, 1);
      break;
    }

    // Plain first line → title
    title = line;
    lines.splice(i, 1);
    break;
  }

  // ----------------------------------------------------------
  // Remaining content
  // ----------------------------------------------------------

  for (const line of lines) {
    bodyLines.push(line);
  }

  if (!title) {
    title = "Untitled Blog";
  }

  return {
    title,
    slug: createSlug(title),
    markdown: bodyLines.join("\n").trim()
  };
}


// ============================================================
// SLUG
// ============================================================

function createSlug(title) {

  return title
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^\w\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
}


// ============================================================
// INLINE MARKDOWN → LEXICAL
// ============================================================

function inlineText(text) {

  const children = [];

  // Basic Markdown:
  // **bold**
  // *italic*
  // [link](url)

  const regex =
    /(\*\*(.+?)\*\*|\*(.+?)\*|\[([^\]]+)\]\((https?:\/\/[^\s)]+)\))/g;

  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {

    // Text before formatting
    if (match.index > lastIndex) {

      children.push({
        detail: 0,
        format: 0,
        mode: "normal",
        style: "",
        text: text.slice(lastIndex, match.index),
        type: "extended-text",
        version: 1
      });

    }

    // Bold
    if (match[2]) {

      children.push({
        detail: 0,
        format: 1,
        mode: "normal",
        style: "",
        text: match[2],
        type: "extended-text",
        version: 1
      });

    }

    // Italic
    else if (match[3]) {

      children.push({
        detail: 0,
        format: 2,
        mode: "normal",
        style: "",
        text: match[3],
        type: "extended-text",
        version: 1
      });

    }

    // Link
    else if (match[4] && match[5]) {

      children.push({
        children: [
          {
            detail: 0,
            format: 0,
            mode: "normal",
            style: "",
            text: match[4],
            type: "extended-text",
            version: 1
          }
        ],
        direction: "ltr",
        format: "",
        indent: 0,
        type: "link",
        version: 1,
        url: match[5],
        rel: null,
        target: null
      });

    }

    lastIndex = regex.lastIndex;
  }

  // Remaining text
  if (lastIndex < text.length) {

    children.push({
      detail: 0,
      format: 0,
      mode: "normal",
      style: "",
      text: text.slice(lastIndex),
      type: "extended-text",
      version: 1
    });

  }

  if (children.length === 0) {

    children.push({
      detail: 0,
      format: 0,
      mode: "normal",
      style: "",
      text: text,
      type: "extended-text",
      version: 1
    });

  }

  return children;
}


// ============================================================
// LEXICAL HELPERS
// ============================================================

function paragraph(text) {

  return {
    children: inlineText(text),
    direction: "ltr",
    format: "",
    indent: 0,
    type: "paragraph",
    version: 1
  };

}


function heading(text, tag = "h2") {

  return {
    children: inlineText(text),
    direction: "ltr",
    format: "",
    indent: 0,
    tag,
    type: "heading",
    version: 1
  };

}


function listItem(text) {

  return {
    children: [
      paragraph(text)
    ],
    direction: "ltr",
    format: "",
    indent: 0,
    type: "listitem",
    version: 1
  };

}


function list(items, ordered = false) {

  return {
    children: items.map(item => listItem(item)),
    direction: "ltr",
    format: "",
    indent: 0,
    type: "list",
    version: 1,
    listType: ordered ? "number" : "bullet",
    start: 1,
    tag: ordered ? "ol" : "ul"
  };

}


// ============================================================
// BUILD LEXICAL FROM MARKDOWN
// ============================================================

function markdownToLexical(markdown) {

  const lines = markdown
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .split("\n");

  const children = [];

  let paragraphBuffer = [];
  let bulletBuffer = [];
  let numberedBuffer = [];


  function flushParagraph() {

    if (paragraphBuffer.length === 0) {
      return;
    }

    const text = paragraphBuffer
      .join(" ")
      .trim();

    if (text) {
      children.push(paragraph(text));
    }

    paragraphBuffer = [];
  }


  function flushLists() {

    if (bulletBuffer.length > 0) {

      children.push(
        list(bulletBuffer, false)
      );

      bulletBuffer = [];
    }

    if (numberedBuffer.length > 0) {

      children.push(
        list(numberedBuffer, true)
      );

      numberedBuffer = [];
    }

  }


  for (const originalLine of lines) {

    const line = originalLine.trim();


    // Empty line
    if (!line) {

      flushParagraph();
      flushLists();

      continue;
    }


    // Horizontal rule
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(line)) {

      flushParagraph();
      flushLists();

      continue;
    }


    // H1
    if (/^#\s+/.test(line)) {

      flushParagraph();
      flushLists();

      children.push(
        heading(
          line.replace(/^#\s+/, "").trim(),
          "h1"
        )
      );

      continue;
    }


    // H2
    if (/^##\s+/.test(line)) {

      flushParagraph();
      flushLists();

      children.push(
        heading(
          line.replace(/^##\s+/, "").trim(),
          "h2"
        )
      );

      continue;
    }


    // H3
    if (/^###\s+/.test(line)) {

      flushParagraph();
      flushLists();

      children.push(
        heading(
          line.replace(/^###\s+/, "").trim(),
          "h3"
        )
      );

      continue;
    }


    // Bullet
    const bulletMatch =
      line.match(/^[-*+]\s+(.+)$/);

    if (bulletMatch) {

      flushParagraph();

      if (numberedBuffer.length > 0) {
        flushLists();
      }

      bulletBuffer.push(
        bulletMatch[1]
      );

      continue;
    }


    // Numbered list
    const numberedMatch =
      line.match(/^\d+[.)]\s+(.+)$/);

    if (numberedMatch) {

      flushParagraph();

      if (bulletBuffer.length > 0) {
        flushLists();
      }

      numberedBuffer.push(
        numberedMatch[1]
      );

      continue;
    }


    // Normal paragraph
    flushLists();

    paragraphBuffer.push(line);
  }


  flushParagraph();
  flushLists();


  return children;
}


// ============================================================
// 6. Build Lexical
// ============================================================

let children = [];


// ------------------------------------------------------------
// JSON output
// ------------------------------------------------------------

if (blog.sections && Array.isArray(blog.sections)) {

  if (blog.introduction) {
    children.push(
      paragraph(
        blog.introduction.trim()
      )
    );
  }


  for (const section of blog.sections) {

    if (section.heading) {

      children.push(
        heading(
          section.heading.trim()
        )
      );

    }

    if (section.content) {

      children.push(
        paragraph(
          section.content.trim()
        )
      );

    }

  }


  if (
    blog.key_takeaways &&
    Array.isArray(blog.key_takeaways) &&
    blog.key_takeaways.length > 0
  ) {

    children.push(
      heading("Key Takeaways")
    );

    children.push(
      list(
        blog.key_takeaways.map(
          item => String(item)
        ),
        false
      )
    );

  }


  if (blog.conclusion) {

    children.push(
      heading("Conclusion")
    );

    children.push(
      paragraph(
        blog.conclusion.trim()
      )
    );

  }

}


// ------------------------------------------------------------
// Markdown/plain-text output
// ------------------------------------------------------------

else {

  children = markdownToLexical(
    blog.markdown
  );

}


// ============================================================
// 7. Ghost Lexical object
// ============================================================

const lexical = {

  root: {
    children,
    direction: "ltr",
    format: "",
    indent: 0,
    type: "root",
    version: 1
  }

};


// ============================================================
// 8. Ghost payload
// ============================================================

return [
  {
    json: {
      posts: [
        {
          title : blog.title,
          slug : blog.slug || createSlug(blog.title),
          lexical : JSON.stringify(lexical),
          status : "published"
        }
      ]
    }
  }
];

const crypto = require('crypto');
const data = $('Data').first().json;
// Put your Ghost Admin API key here
const ghostAdminKey =  $env.GHOST_ADMIN_API_KEY ;

// Split the key into ID and secret
const [keyId, secret] = ghostAdminKey.split(':');

if (!keyId || !secret) {
  throw new Error('Invalid Ghost Admin API key. Expected ID:SECRET');
}

// Base64URL encoder
function base64url(input) {
  return Buffer.from(input)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

// Current Unix timestamp
const now = Math.floor(Date.now() / 1000);

// JWT header
const header = {
  alg: 'HS256',
  typ: 'JWT',
  kid: keyId,
};

// JWT payload
const payload = {
  iat: now,
  exp: now + 300,
  aud: '/admin/',
};

// Encode header + payload
const encodedHeader = base64url(JSON.stringify(header));
const encodedPayload = base64url(JSON.stringify(payload));

const unsignedToken = `${encodedHeader}.${encodedPayload}`;

// Sign using Ghost's hexadecimal secret
const signature = crypto
  .createHmac('sha256', Buffer.from(secret, 'hex'))
  .update(unsignedToken)
  .digest();

const encodedSignature = base64url(signature);

// Final JWT
const token = `${unsignedToken}.${encodedSignature}`;

// Return token for the next node
return [
  {
    json: {
      ...data,
      token
    }
  }
];
